class AtlasDesign(TypedDict, total=False):
    """A structured sign-in page design: OVERRIDES on top of a preset (every field optional; unset
    fields come from the preset, then the defaults). Unknown keys are refused. Colours are
    #RRGGBB; images are uploaded design asset ids (dasset_…), never URLs; fonts are ids from GET
    /v1/design/catalog. There is no field for raw CSS or HTML.
    """
    version: Literal[1]
    preset: Literal['minimal', 'atlas', 'glass', 'midnight', 'editorial', 'terminal', 'sunrise', 'forest', 'grape', 'slate', 'split-photo', 'bold']
    colorScheme: Literal['auto', 'light', 'dark']
    palette: AtlasDesignPalette
    paletteDark: AtlasDesignPalette
    typography: AtlasDesignTypography
    shape: AtlasDesignShape
    elevation: AtlasDesignElevation
    spacing: AtlasDesignSpacing
    card: AtlasDesignCard
    layout: AtlasDesignLayout
    buttons: AtlasDesignButtons
    inputs: AtlasDesignInputs
    background: AtlasDesignBackground
    backgroundDark: AtlasDesignBackground
    logo: AtlasDesignLogo


class ResolvedDesign(TypedDict):
    """The fully-resolved design every surface renders (defaults ← preset ← overrides): the same
    shape as AtlasDesign with every field present.
    """
    version: Literal[1]
    preset: str
    colorScheme: Literal['auto', 'light', 'dark']
    #: Every palette slot, as #rrggbb.
    palette: dict[str, str]
    #: Every palette slot, as #rrggbb.
    paletteDark: dict[str, str]
    typography: dict[str, Any]
    shape: dict[str, Any]
    elevation: dict[str, Any]
    spacing: dict[str, Any]
    card: dict[str, Any]
    layout: dict[str, Any]
    buttons: dict[str, Any]
    inputs: dict[str, Any]
    background: dict[str, Any]
    backgroundDark: dict[str, Any]
    logo: dict[str, Any]


class DesignWarning(TypedDict):
    """A contrast warning (advice, never a refusal): a text/background pair below WCAG AA 4.5:1."""
    code: Literal['low_contrast']
    mode: Literal['light', 'dark']
    pair: list[str]
    ratio: float
    required: float
    #: The setting to change, e.g. palette.primaryInk.
    path: str
    message: str


