    #: Removes tags without touching the others.
    requireMfaReasonsRemove: list[str]
    mfaEnforcement: Literal['withhold_claims', 'require_step_up', None]
    mfaMaxAgeSeconds: int | None
    allowedMfaFactors: list[Literal['totp', 'sms', 'passkey', 'push']] | None
    requiredFactors: list[Literal['totp', 'sms', 'passkey', 'push']] | None
    #: Tighten-only password rules layered over the instance policy: minLength, bannedPasswords, and checkBreaches/requireUppercase/requireLowercase/requireN
    passwordPolicyOverride: dict[str, Any] | None
    ssoRequired: bool | None
    sessionIdleOverrideMs: int | None
    #: Restrict which sign-in methods a member may use (e.g. "password", "oauth:google", "saml", "magic_link"). null CLEARS the override (all methods). Unkno
    allowedSignInMethods: list[str] | None
    #: CIDR allow-list gating member sign-in. null CLEARS the override. A bad CIDR → 400.
    ipAllowlist: list[str] | None
    #: Cap the absolute session lifetime for members, in seconds (300 … 7776000). null CLEARS the override.
    maxSessionAgeSeconds: int | None
    #: Cap on the concurrent active sessions of each member (1 … 100). null CLEARS the override.
    maxSessions: int | None
    #: Allow the organization more than one enterprise SSO connection. null CLEARS the override.
    ssoMultiConnection: bool | None
    #: Retired (never affected entitlements). Only null is accepted, to clear a stored value; any other value → 422. Grant an org a plan/features/limits with
    entitlementPlan: None
    #: Retired — see entitlementPlan. Only null (clear) is accepted.
    entitlementOverrides: None
    #: What ordinary members see of each other in Frontend API member lists: directory (default: name and picture) or private (member id and role only). Memb
    memberVisibility: Literal['directory', 'private', None]
    endUserPool: OrgPolicyEndUserPool | None
    #: Break-glass email addresses (at most 20) allowed to use a password while ssoRequired is on. null CLEARS the list.
    ssoBypass: list[str] | None
    #: Technical contacts (at most 10). null CLEARS the list.
    itContacts: list[OrgPolicyItContactsItem] | None


